import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './card.module.css'

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * `default` draws a 1px border, `outlined` a heavier one, `elevated` drops the border for
   * a shadow.
   *
   * @defaultValue `default`
   * @see the component manifest
   */
  variant?: 'default' | 'outlined' | 'elevated'
  /**
   * Inner padding of the CARD BOX. ⚠ `padding="none"` deliberately does NOT strip the
   * padding from CardHeader/CardContent/CardFooter — those keep their own. It means "let a
   * flush child (a LogViewer, an image, an edge-to-edge table) reach the card's edge";
   * zeroing both put the title flush against the border and made the mode unusable with the
   * composition it exists for. For an edge-to-edge table, skip CardContent and pass the
   * table as a direct child.
   *
   * @defaultValue `md`
   * @see the component manifest
   */
  padding?: 'none' | 'sm' | 'md' | 'lg'
  /**
   * AI presence: `true` gives the surface an AI-tinted edge and a soft aura, marking
   * AI-generated content; `'generating'` adds a pulsing inner glow while AI is still
   * producing it (stops under reduced motion). Visual only — pair it with an AiBadge so the
   * provenance is also text.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  ai?: boolean | 'generating'
}

export function Card({
  variant = 'default',
  padding = 'md',
  ai = false,
  className,
  children,
  ...props
}: CardProps) {
  return (
    <div
      data-cascivo-card=""
      data-variant={variant}
      data-padding={padding}
      data-ai={ai === 'generating' ? 'generating' : ai ? '' : undefined}
      className={cn(styles['card'], className)}
      {...props}
    >
      {children}
    </div>
  )
}

export interface CardHeaderProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Trailing content pinned to the inline-end of the header — an overflow menu, a status
   * badge, a link. Without it the header is a column (title over description), which is
   * why `justify-content: space-between` alone does nothing: the most common dashboard
   * card layout is title-left / action-right, and it needs a row.
   *
   * The title column keeps `min-inline-size: 0`, so a long title truncates instead of
   * pushing the actions out of the card.
   */
  actions?: ReactNode
}

export function CardHeader({ actions, className, children, ...props }: CardHeaderProps) {
  if (actions === undefined) {
    return (
      <div className={cn(styles['header'], className)} {...props}>
        {children}
      </div>
    )
  }
  return (
    <div className={cn(styles['header'], styles['headerRow'], className)} {...props}>
      <div className={styles['headerMain']}>{children}</div>
      <div className={styles['headerActions']}>{actions}</div>
    </div>
  )
}

export interface CardTitleProps extends HTMLAttributes<HTMLHeadingElement> {}

export function CardTitle({ className, children, ...props }: CardTitleProps) {
  return (
    <h3 className={cn(styles['title'], className)} {...props}>
      {children}
    </h3>
  )
}

export interface CardContentProps extends HTMLAttributes<HTMLDivElement> {}

export function CardContent({ className, children, ...props }: CardContentProps) {
  return (
    <div className={cn(styles['content'], className)} {...props}>
      {children}
    </div>
  )
}

export interface CardFooterProps extends HTMLAttributes<HTMLDivElement> {}

export function CardFooter({ className, children, ...props }: CardFooterProps) {
  return (
    <div className={cn(styles['footer'], className)} {...props}>
      {children}
    </div>
  )
}

@layer cascivo.component {
  .card {
    /* Containing block for the stretched-link pattern (an <a> with
       `::after { position: absolute; inset: 0 }` making the whole card clickable — what every
       dashboard project grid does). Without it the overlay resolves against the VIEWPORT and
       covers the entire application: the sidebar and header stop responding to clicks, with
       nothing on screen to suggest why. Reported 2026-08-08 (report A) after a Playwright
       click timed out; a human would only have found it by being very confused. */
    position: relative;
    background-color: var(--cascivo-color-surface);
    border-radius: var(--cascivo-radius-surface);
    overflow: hidden;
    padding: var(--_card-p, 0);

    /* When the card holds its own subcomponents, THEY own the inset — otherwise both pad and
       the header's content sits 48px from the border at the default size (measured in
       Chromium by scripts/checks/computed-style.test.ts, which is the only kind of test that
       can see it). Raw children still get the card's padding, which is what it is for. */
    &:has(> .header, > .content, > .footer) {
      padding: 0;
    }

    /* `--_card-p` is the CARD BOX's own padding; `--_card-inner-p` is what CardHeader /
       CardContent / CardFooter use. They are separate because `padding="none"` means
       "let a flush child (a LogViewer, an image) reach the card's edge" — it must not
       also strip the padding from the subcomponents the card exists to hold. Setting
       both to 0 put CardHeader's title flush against the border, which made
       `padding="none"` unusable with the very composition it is for. */
    &[data-padding='none'] {
      --_card-p: 0;
      /* deliberately no --_card-inner-p: subcomponents keep their own default */
    }
    &[data-padding='sm'] {
      --_card-p: var(--cascivo-space-4);
      --_card-inner-p: var(--cascivo-space-4);
    }
    &[data-padding='md'] {
      --_card-p: var(--cascivo-space-6);
      --_card-inner-p: var(--cascivo-space-6);
    }
    &[data-padding='lg'] {
      --_card-p: var(--cascivo-space-8);
      --_card-inner-p: var(--cascivo-space-8);
    }

    &[data-variant='default'] {
      border: 1px solid var(--cascivo-color-border);
    }

    &[data-variant='outlined'] {
      border: 1.5px solid var(--cascivo-color-border-strong);
    }

    &[data-variant='elevated'] {
      border: none;
      box-shadow: var(--cascivo-shadow-md);
    }

    /* AI presence: an AI-tinted edge and a soft aura rising from the bottom. A static mark
       of AI content — after the variant rules so it restates the border on every variant. */
    &[data-ai] {
      border: 1px solid var(--cascivo-color-ai-border);
      background-image: linear-gradient(to top, var(--cascivo-color-ai-subtle), transparent 60%);
    }

    /* Generation in progress adds an inner glow on its own layer, so the loop below animates
       only its opacity. At rest (and under reduced motion) the glow simply stays on. */
    &[data-ai='generating']::before {
      content: '';
      position: absolute;
      inset: 0;
      border-radius: inherit;
      box-shadow:
        inset 0 0 0 1px var(--cascivo-color-ai),
        inset 0 0 1.5rem var(--cascivo-color-ai-sheen);
      pointer-events: none;
    }
  }

  /* Decorative loop — opt-in. Rovo's rule: an animated AI edge means work in progress. */
  @media (prefers-reduced-motion: no-preference) {
    .card[data-ai='generating']::before {
      animation: global(cascivo-pulse) var(--cascivo-duration-loop-slow) var(--cascivo-ease-in-out)
        infinite;
    }
  }

  .header {
    padding: var(--_card-inner-p, var(--cascivo-space-6));
    padding-block-end: 0;
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    /* Allow this flex section to shrink inside the card instead of forcing its
       content past the card's clipping edge (overflow: hidden above). */
    min-inline-size: 0;
  }

  /* Title + trailing actions (CardHeader `actions`). The default header is a column
     (title over description), so the row variant is opt-in: `justify-content` alone on a
     column does nothing, which is the trap the most common dashboard card layout hits. */
  .headerRow {
    flex-direction: row;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--cascivo-space-3);

    /* Let the text column shrink so a long title truncates instead of pushing the
       actions past the card's clipping edge. */
    .headerMain {
      display: flex;
      flex-direction: column;
      gap: var(--cascivo-space-1);
      min-inline-size: 0;
    }

    .headerActions {
      display: flex;
      align-items: center;
      gap: var(--cascivo-space-1);
      flex-shrink: 0;
    }
  }

  .title {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-lg);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-tight);
    margin: 0;
  }

  .content {
    padding: var(--_card-inner-p, var(--cascivo-space-6));
    color: var(--cascivo-color-text-subtle);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-relaxed);
  }

  .footer {
    padding: var(--_card-inner-p, var(--cascivo-space-6));
    padding-block-start: 0;
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    min-inline-size: 0;

    /* Let direct children (e.g. a label beside a status Badge) shrink below their
       intrinsic width so a long label doesn't push a trailing item past the card's
       clipping edge. A child that must not shrink can set flex-shrink: 0 itself. */
    & > * {
      min-inline-size: 0;
    }
  }
}

@media (forced-colors: active) {
  .card[data-ai] {
    border-color: Highlight;
  }
}
